def race_class_recommendation_text(race_name):
    data = RACE_CLASS_RECOMMENDATIONS.get(race_name)
    if not data:
        return ""
    return f"Polecane klasy: {', '.join(data['classes'])}. Dlaczego: {data['reason']}."

