def _v012_connect(a, direction_a, b, direction_b):
    ROOMS[a].setdefault("exits", {})[direction_a] = b
    ROOMS[b].setdefault("exits", {})[direction_b] = a


def _v012_add_room(room_id, zone, name, desc):
    ROOMS[room_id] = {
        "zone": zone,
        "name": name,
        "desc": desc,
        "exits": {},
    }


