def v0260_museum_rank(percent):
    percent = max(0, min(100, int(percent)))
    if percent >= 100:
        return "Legenda Muzeum"
    if percent >= 90:
        return "Strażnik Dziedzictwa"
    if percent >= 75:
        return "Mistrz Muzeum"
    if percent >= 50:
        return "Kustosz"
    if percent >= 25:
        return "Badacz Dziedzictwa"
    if percent >= 10:
        return "Kolekcjoner"
    return "Nowicjusz"


